# filename: tools/counter.py
"""[12] stand-in for Flink: Kinesis -> rolling 5-minute count per card -> DynamoDB."""
import asyncio, bisect, json, os, time
from collections import OrderedDict
from datetime import datetime

import aioboto3
from botocore.config import Config
from botocore.exceptions import ClientError

STREAM = os.getenv("KINESIS_STREAM", "payment-events")
TABLE = os.getenv("FEATURE_TABLE", "card_features")
WINDOW_S = int(os.getenv("WINDOW_S", "300"))
START_AT = os.getenv("START_AT", "LATEST")      # LATEST: ignore old records in the stream
POLL_S = float(os.getenv("POLL_S", "0.1"))

windows = {}             # card_token -> sorted event-time epoch seconds inside the window
seen = OrderedDict()     # event_id -> None; ignores duplicate deliveries (Kinesis is at-least-once)
watermark = 0.0          # newest event time seen; event time, not wall-clock


def add(rec):
    """Add one record to its card's window. Returns the card token, or None for a duplicate."""
    global watermark
    if rec["event_id"] in seen:
        return None
    seen[rec["event_id"]] = None
    if len(seen) > 200_000:
        seen.popitem(last=False)
    et = datetime.fromisoformat(rec["event_time"]).timestamp()
    watermark = max(watermark, et)
    bisect.insort(windows.setdefault(rec["card_token"], []), et)
    return rec["card_token"]


def window_count(token):
    w = windows[token]
    del w[:bisect.bisect_right(w, watermark - WINDOW_S)]    # drop events older than the window
    return len(w)


def expired():
    """Cards with an event that has aged out; their stored count is now too high."""
    cut = watermark - WINDOW_S
    return {t for t, w in windows.items() if w and w[0] <= cut}


async def write(table, token, sem):
    count = window_count(token)
    if count == 0:
        del windows[token]
    async with sem:
        try:
            await table.update_item(                    # update, not put: keeps devices and averages
                Key={"card_token": token},
                UpdateExpression="SET txn_count_5m = :c, updated_at = :u",
                ConditionExpression="attribute_exists(card_token)",   # never create unknown cards
                ExpressionAttributeValues={":c": count, ":u": int(time.time())})
        except ClientError as e:
            if e.response["Error"]["Code"] != "ConditionalCheckFailedException":
                print("write failed", token, e, flush=True)
        except Exception as e:                          # timeout etc.: log and keep running
            print(f"write failed {token}: {type(e).__name__}", flush=True)


async def shard_iterator(kin, shard, kind, seq=None):
    args = dict(StreamName=STREAM, ShardId=shard, ShardIteratorType=kind)
    if seq:
        args["StartingSequenceNumber"] = seq
    return (await kin.get_shard_iterator(**args))["ShardIterator"]


async def main():
    cfg = Config(connect_timeout=2, read_timeout=15, max_pool_connections=100,
                 retries={"max_attempts": 1, "mode": "standard"})
    sess = aioboto3.Session()
    async with sess.client("kinesis", config=cfg) as kin, sess.resource("dynamodb", config=cfg) as ddb:
        table = await ddb.Table(TABLE)
        iters, last_seq = {}, {}
        for s in (await kin.list_shards(StreamName=STREAM))["Shards"]:
            iters[s["ShardId"]] = await shard_iterator(kin, s["ShardId"], START_AT)
        print(f"counter listening on {STREAM} ({len(iters)} shard, start={START_AT})", flush=True)

        sem = asyncio.Semaphore(50)
        total, last_total, max_lag = 0, -1, 0.0
        last_sweep = last_print = time.monotonic()
        while True:
            touched, arrived = set(), []
            for shard, it in list(iters.items()):
                try:
                    r = await kin.get_records(ShardIterator=it, Limit=500)
                except Exception as e:                  # slow or broken read: log, resume, keep running
                    print(f"get_records failed ({type(e).__name__}); retrying", flush=True)
                    await asyncio.sleep(1)
                    if shard in last_seq:               # restart just after the last record handled
                        try:
                            iters[shard] = await shard_iterator(
                                kin, shard, "AFTER_SEQUENCE_NUMBER", last_seq[shard])
                        except Exception:
                            pass
                    continue
                iters[shard] = r["NextShardIterator"]
                if r["Records"]:
                    last_seq[shard] = r["Records"][-1]["SequenceNumber"]
                for rec in r["Records"]:
                    arrived.append(rec["ApproximateArrivalTimestamp"].timestamp())
                    token = add(json.loads(rec["Data"]))
                    if token:
                        touched.add(token)
                        total += 1
            if time.monotonic() - last_sweep >= 1:
                touched |= expired()
                last_sweep = time.monotonic()
            if touched:
                await asyncio.gather(*(write(table, t, sem) for t in touched))
            if arrived:                                  # delay from stream arrival to written in DynamoDB
                max_lag = max(max_lag, time.time() - min(arrived))
            if time.monotonic() - last_print >= 5:
                if total != last_total:                  # stay quiet when nothing is happening
                    print(f"events={total} cards_tracked={len(windows)} max_lag_s={max_lag:.2f}", flush=True)
                    last_total = total
                last_print = time.monotonic()
            await asyncio.sleep(POLL_S)


asyncio.run(main())
